	localAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
	if err == nil {
		if _, statErr := os.Stat(localAbs); statErr == nil {
			return settings.EntireSettingsLocalFile, configDisplayLocal
		}
